    /// Extracts the first grapheme cluster of the string.
    /// Fails with an error if the string is empty.
    ///
    /// If `count` is given, returns an array with that many of the first
    /// grapheme clusters instead. Fails with an error if the string has fewer
    /// grapheme clusters than requested.
    #[func]
    pub fn first(
        &self,
        /// Number of characters to return as an array. If omitted, returns a
        /// single string.
        #[named]
        count: Option<usize>,
        /// A set of characters to remove from the start of the string before
        /// the first grapheme cluster is extracted. If the string is empty
        /// after removing them, this fails with an error.
        #[named]
        strip: Option<Str>,
    ) -> StrResult<Value> {
        let mut s = self.as_str();
        if let Some(strip) = &strip {
            let chars: Vec<char> = strip.as_str().chars().collect();
            s = s.trim_start_matches(chars.as_slice());
        }

        let Some(count) = count else {
            let cluster = s.graphemes(true).next();
            return cluster.map(IntoValue::into_value).ok_or_else(string_is_empty);
        };

        check_count(count)?;
        let clusters: Vec<&str> = s.graphemes(true).take(count).collect();
        if clusters.len() < count {
            return Err(not_enough_characters(count, s.graphemes(true).count()));
        }
        Ok(clusters_to_array(clusters))
    }

